#include <Servo.h> // Подключаем библиотеку для работы с сервоприводами

// Назначаем используемые пины
const int SERVO_1_PIN = 2;      // D2 servo for doors open
const int SERVO_2_PIN = 3;      // D3 servo for laser movement
const int OUT_1_PIN = 4;        // D4 laser power
const int WHITE_LED_PIN = 5;    // D5 White LED in lense
const int ORANGE_LED_PIN = 6;   // D6 Yellow LED in lense
const int RED_LED_PIN = 7;      // D7 Red LED in lense
const int WHITE_LED_2_PIN = 8;  // D8 White LED in antennas
const int RED_LED_2_PIN = 9;    // D9 White LED in antennas
const int OUT_2_PIN = 10;       // D10 LED in weapon (2 sides)
const int OUT_3_PIN = 11;       // D11 left weapon 
const int OUT_4_PIN = 12;       // D12 right weapon
const int OUT_5_PIN = 13;       // D13 reserve (activateted with case 2)
const int SOUND_SENSOR_PIN = A1; // Вход датчика звука

// Системные переменные
int state = 0;                    // Счетчик состояний (0, 1 или 2)
unsigned long lastSoundTime = 0;  // Время последнего срабатывания датчика
unsigned long lastBlinkTime = 0;  // Время последнего мигания светодиода

// Объекты для сервоприводов
Servo servo1;
Servo servo2;

void setup() {
                                  // Инициализируем последовательный порт
  Serial.begin(9600);

  // Настраиваем выводы
  pinMode(OUT_1_PIN, OUTPUT);
  pinMode(WHITE_LED_PIN, OUTPUT);
  pinMode(ORANGE_LED_PIN, OUTPUT);
  pinMode(RED_LED_PIN, OUTPUT);
  pinMode(WHITE_LED_2_PIN, OUTPUT);
  pinMode(RED_LED_2_PIN, OUTPUT);
  pinMode(OUT_2_PIN, OUTPUT);
  pinMode(OUT_3_PIN, OUTPUT);
  pinMode(OUT_4_PIN, OUTPUT);
  pinMode(OUT_5_PIN, OUTPUT);
  // Присоединяем сервоприводы
  servo1.attach(SERVO_1_PIN);
  servo2.attach(SERVO_2_PIN);

  // Стартуем с режима 1
  setMode(state);
}

void loop() {
  // Проверяем показания датчика звука
  checkSoundSensor();

  // Если прошло 6 секунд без новой активности, сбрасываем счетчик
  if (state != 0 && millis() - lastSoundTime > 6000) {
    state = 0;
    setMode(state);
  }

  // Периодически мигнем светодиодом каждые 3 секунды
  if (millis() - lastBlinkTime >= 3000) {
    digitalWrite(WHITE_LED_2_PIN, HIGH);   // ВКЛ
    delay(300);                            // ждём 300 мс
    digitalWrite(WHITE_LED_2_PIN, LOW);    // ВЫКЛ
    lastBlinkTime = millis();              // запоминаем время мигания
  }

  // Выводим текущий режим в последовательный порт
  Serial.print("Режим: ");
  Serial.println(state);
}

// Метод для обработки показаний датчика звука
void checkSoundSensor() {
  int soundValue = analogRead(SOUND_SENSOR_PIN); // Читаем показания с датчика
  if (soundValue > 500) {                        // Если значение выше 500
    if (millis() - lastSoundTime >3500) {        // Повторная проверка допустима через 3,5 секунды
      state++;                                   // Увеличиваем счетчик
      if (state > 2) state = 0;                  // Максимальное значение счетчика - 2
      setMode(state);                            // Устанавливаем новый режим
      lastSoundTime = millis();                  // Запоминаем время последнего срабатывания
    }
  }
}

