      digitalWrite(OUT_1_PIN, LOW);            // D4 = 0
      digitalWrite(ORANGE_LED_PIN, LOW);       // D6 = 0
      digitalWrite(RED_LED_2_PIN, HIGH);       // D9 = 1
      digitalWrite(OUT_2_PIN, HIGH);           // D10 = 1
      digitalWrite(OUT_3_PIN, HIGH);           // D11 = 1
      digitalWrite(OUT_4_PIN, HIGH);
      digitalWrite(OUT_5_PIN, HIGH);
      delay (2000);
      break;
  }
}

// Перемещение сервопривода 2 вперед-назад 10 раз
void moveServo2() {
  for (int i = 0; i < 10; i++) {
    for (int pos = 0; pos <= 35; pos++) {
      servo2.write(pos);                      // Положение от 0 до 35 градусов
      delay(8);                               // Задержка между шагами 8 мс
    }
    for (int pos = 35; pos >= 0; pos--) {
      servo2.write(pos);                      // Обратное движение
      delay(8);                               // Задержка между шагами 8 мс
    }
  }
}
